#!/usr/bin/env node
// Builds dist/qrast-setup.sql: one file to paste into a NEW client's
// Supabase SQL Editor (never the live Victoria project).
//
// Contents, in order:
//   1. The base schema (schema-dump.sql by default) -- the 13 tables that
//      were built in the dashboard and have no CREATE TABLE in git. See
//      SCHEMA-EXPORT-README.md for how to produce it with pg_dump. The bundle
//      refuses to build without it, because every migration below assumes
//      public.users etc. already exist.
//   2. Every migrate-*.sql file, in the order they were applied to Victoria
//      (first-commit order in git). New migration files must be added to
//      MIGRATIONS below; the script fails if one is missing from the list.
//
// Usage:
//   node build-sql-bundle.mjs                    # base = schema-dump.sql
//   node build-sql-bundle.mjs --base other.sql
//
// Needs Node 18+. No npm install required.

import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync } from 'node:fs';

const MIGRATIONS = [
  'migrate-system-settings.sql',
  'migrate-consent-and-support-tickets.sql',
  'migrate-coordinator-qr-authorization.sql',
  'migrate-coordinator-users-columns.sql',
  'migrate-sessions-insert-policy.sql',
  'migrate-faculty-scoped-reads.sql',
  'migrate-system-settings-insert-policy.sql',
  'migrate-account-deletion-requests.sql',
  'migrate-users-self-service-update.sql',
  'migrate-term-start-date.sql',
  'migrate-attendance-marks.sql',
  'migrate-harden-users-privilege-escalation.sql',
  'migrate-rate-limits.sql',
  'migrate-announcements.sql',
  'migrate-coordinator-limit.sql',
  'migrate-classes-year-column.sql',
  'migrate-live-sessions-class-id.sql',
  'migrate-academic-year-archive.sql',
  'migrate-academic-calendar.sql',
  'migrate-notification-threads.sql',
  'migrate-notification-reply-policy.sql',
  'migrate-server-side-checkin.sql',
  'migrate-backup-pin-expiry.sql',
  'migrate-lock-direct-attendance-insert.sql',
];

const baseFlag = process.argv.indexOf('--base');
const BASE = baseFlag !== -1 ? process.argv[baseFlag + 1] : 'schema-dump.sql';

const onDisk = readdirSync('.').filter(f => /^migrate-.*\.sql$/.test(f));
const unlisted = onDisk.filter(f => !MIGRATIONS.includes(f));
const missing = MIGRATIONS.filter(f => !onDisk.includes(f));
if (unlisted.length || missing.length) {
  if (unlisted.length) console.error('Not in MIGRATIONS (add in the right order): ' + unlisted.join(', '));
  if (missing.length) console.error('Listed but not found: ' + missing.join(', '));
  process.exit(1);
}

if (!BASE || !existsSync(BASE)) {
  console.error(`Base schema "${BASE}" not found. Produce it first (SCHEMA-EXPORT-README.md, Option A),`);
  console.error('or point at it with --base <file>.');
  process.exit(1);
}

// pg_dump 17.6+/18 emits psql-only meta-commands (\restrict, \unrestrict)
// that the Supabase SQL Editor rejects, and `SET transaction_timeout`, which
// servers older than Postgres 17 do not know. Strip them from the base.
const base = readFileSync(BASE, 'utf8')
  .replace(/^﻿/, '')
  .split(/\r?\n/)
  .filter(line => !/^\\(un)?restrict\b/.test(line) && !/^SET transaction_timeout\b/.test(line))
  .join('\n');

const parts = [
  '-- QRAST setup bundle, generated by build-sql-bundle.mjs. Do not edit by hand.',
  '-- Run on a NEW, empty Supabase project only.',
  '',
  `-- ===== base schema: ${BASE} =====`,
  base,
];
for (const f of MIGRATIONS) {
  parts.push('', `-- ===== ${f} =====`, readFileSync(f, 'utf8'));
}

mkdirSync('dist', { recursive: true });
writeFileSync('dist/qrast-setup.sql', parts.join('\n'));
console.log(`Wrote dist/qrast-setup.sql (base + ${MIGRATIONS.length} migrations).`);
